export const EPBD_TROSKEL_2030 = 217;
export const EPBD_TROSKEL_2033 = 176;

export const PEF_BARARE: Record<string, number> = { el:1.8, fjv:0.7, fjk:0.6, olja:1.8, pellets:0.6 };
export const BARARE_LABEL: Record<string, string> = { el:'El', fjv:'Fjärrvärme', fjk:'Fjärrkyla', olja:'Olja', pellets:'Pellets' };

// Recompute e30/e33 from current PET thresholds (mirrors init() in source)
for (const f of FASTIGHETER_RAW) {
  if (f.pet !== null && f.pet !== undefined) {
    f.e30 = f.pet > EPBD_TROSKEL_2030 ? 'JA' : 'NEJ';
    f.e33 = f.pet > EPBD_TROSKEL_2033 ? 'JA' : 'NEJ';
  } else {
    f.e30 = '';
    f.e33 = '';
  }
}
